    /*
     * Add to the Lines
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	GoodsReceipt
     */
    public GoodsReceipt addToLines( UUID parentId, GoodsReceiptLine addTo ) {
	    LOGGER.info("handling AssignLinesToGoodsReceiptEvent - " );
	    
	    GoodsReceipt parentEntity = repository.findById(parentId).get();
	    GoodsReceiptLine child = registry.project( GoodsReceiptLine.class, addTo.getGoodsReceiptLineId());
	    
	    parentEntity.getLines().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Lines
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	GoodsReceipt
     */
	public GoodsReceipt removeFromLines( UUID parentId, GoodsReceiptLine removeFrom ) {
	    LOGGER.info("handling RemoveLinesFromGoodsReceiptEvent " );
	
	    GoodsReceipt parentEntity = repository.findById(parentId).get();
	    GoodsReceiptLine child = registry.project( GoodsReceiptLine.class, removeFrom.getGoodsReceiptLineId());
	    
	    parentEntity.getLines().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



